theorem my_favorite_theorem (k : ℝ) : 
  let A : ℝ × ℝ := (k, 3)
  let B : ℝ × ℝ := (3, 1)
  let C : ℝ × ℝ := (6, k)
  let AB := Real.sqrt ((B.1 - A.1)^2 + (B.2 - A.2)^2)
  let AC := Real.sqrt ((C.1 - A.1)^2 + (C.2 - A.2)^2)
  AB = AC → (3 - k)^2 + 4 = 45 - 18*k + 2*k^2

